def IsCompactConvexProduct {n : ℕ} (L : Set (FinitePoint n)) : Prop :=
  ∃ C : Fin n → Set ℂ, (∀ k, IsCompact (C k) ∧ Convex ℝ (C k)) ∧
    L = Set.pi univ C

